export type BrowserPhase = 'profileSetupBlocked' | 'operationUncertain' | 'serviceUnavailable' | 'launchCooldown' | 'waitingForOwner' | 'launchBlocked' | 'launchUncertain' | 'providerSetupRequired' | 'profileRequired' | 'browserMissing' | 'viewerUnavailable' | 'ready' | 'signInRequired' | 'needsResolution' | 'needsAttention' | 'stopped' | 'unknown' | 'verified' | 'busy'
export type BrowserStream = { kind: 'voxl'; url: string; page: { width: number; height: number }; window: { left: number; top: number; width: number; height: number } }
export type BrowserCheckView = { phase: BrowserPhase; address?: string | null; canGoBack?: boolean; canNavigate?: boolean; retryAt?: string | null; reason?: { code: string; message: string; recordedAt: string | null }; viewerId: string | null; generation: string | null; revision: string | null; pageState: string | null; canInteract: boolean; canResolve: boolean; canComplete: boolean; stream?: BrowserStream | null }
export type BrowserOperation = 'status' | 'open' | 'linkProfile' | 'verify' | 'resolve' | 'complete' | 'input' | 'back' | 'reload' | 'close'
